    public function fetch_markets($params = array()): array {
        /**
         * retrieves data on all $markets for wallex
         *
         * @see https://developers.wallex.ir
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} an array of objects representing market data
         */
        $response = $this->publicGetV1Markets($params);
        //
        //     {
        //         "result": { "symbols": { "BTCUSDT": { ... }, "USDTTMN": { ... } } },
        //         "message": "The operation was successful",
        //         "success": true
        //     }
        //
        $result = $this->safe_dict($response, 'result', array());
        $symbols = $this->safe_dict($result, 'symbols', array());
        $markets = is_array($symbols) ? array_values($symbols) : array();
        return $this->parse_markets($markets);
    }

    public function parse_market(array $market): array {
        //
        //     {
        //         "symbol": "USDTTMN",
        //         "baseAsset": "USDT",
        //         "baseAssetPrecision": 8,
        //         "quoteAsset": "TMN",
        //         "quotePrecision": 0,
        //         "stepSize": 2,        // amount decimals, not a step
        //         "tickSize": 0,        // price decimals, not a tick
        //         "minQty": 0.01,
        //         "minNotional": 50000,
        //         "stats": { ... },
        //         "createdAt": "2020-12-01T00:00:00Z",
        //         ...
        //     }
        //
        $id = $this->safe_string($market, 'symbol');
        $baseId = $this->safe_string($market, 'baseAsset');
        $quoteId = $this->safe_string($market, 'quoteAsset');
        $base = $this->safe_currency_code($baseId);
        $quote = $this->safe_currency_code($quoteId);
        return $this->safe_market_structure(array(
            'id' => $id,
            'symbol' => $base . '/' . $quote,
            'base' => $base,
            'quote' => $quote,
            'baseId' => $baseId,
            'quoteId' => $quoteId,
            'type' => 'spot',
            'spot' => true,
            'margin' => false,
            'swap' => false,
            'future' => false,
            'option' => false,
            'active' => true,
            'contract' => false,
            'precision' => array(
                'amount' => $this->parse_number($this->parse_precision($this->safe_string($market, 'stepSize'))),
                'price' => $this->parse_number($this->parse_precision($this->safe_string($market, 'tickSize'))),
            ),
            'limits' => array(
                'amount' => array( 'min' => $this->safe_number($market, 'minQty'), 'max' => null ),
                'price' => array( 'min' => null, 'max' => null ),
                'cost' => array( 'min' => $this->safe_number($market, 'minNotional'), 'max' => null ),
                'leverage' => array( 'min' => null, 'max' => null ),
            ),
            'created' => $this->parse8601($this->safe_string($market, 'createdAt')),
            'info' => $market,
        ));
    }

    public function fetch_balance($params = array()): array {
        /**
         * query for balance and get the amount of funds available for trading or funds locked in orders
         *
         * @see https://developers.wallex.ir
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/?id=balance-structure balance structure~
         */
        $this->load_markets();
        $response = $this->privateGetV1AccountBalances($params);
        return $this->parse_balance($response);
    }

    public function parse_balance(mixed $response): array {
        //
        //     {
        //         "result": {
        //             "balances": {
        //                 "BTC": { "asset": "BTC", "faName": "بیت کوین", "fiat": false, "value": "0.5", "locked": "0.1" },
        //                 "TMN": { "asset": "TMN", "faName": "تومان", "fiat": true, "value": "1000000", "locked": "0" }
        //             }
        //         },
        //         "success": true
        //     }
        //
        $result = array( 'info' => $response );
        $data = $this->safe_dict($response, 'result', array());
        $balances = $this->safe_dict($data, 'balances', array());
        $currencyIds = is_array($balances) ? array_keys($balances) : array();
        for ($i = 0; $i < count($currencyIds); $i++) {
            $currencyId = $currencyIds[$i];
            $balance = $this->safe_dict($balances, $currencyId, array());
            $account = $this->account();
            $account['total'] = $this->safe_string($balance, 'value');
            $account['used'] = $this->safe_string($balance, 'locked');
            $code = $this->safe_currency_code($currencyId);
            if ($code !== null) {
                $result[$code] = $account;
            }
        }
        return $this->safe_balance($result);
    }

    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()): array {
        /**
         * create a trade order
         *
         * @see https://developers.wallex.ir/docs/spot-create-order
         *
         * @param {string} $symbol unified $symbol of the $market to create an order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much of the base currency you want to trade
         * @param {float} [$price] the $price at which the order is to be fulfilled, wallex marks it required for every $type
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {float} [$params->triggerPrice] turns the order into STOP_LIMIT or STOP_MARKET
         * @param {string} [$params->clientOrderId] [A-Z0-9_], must be unique
         * @return {array} an ~@link https://docs.ccxt.com/?id=order-structure order structure~
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
            'type' => strtoupper($type),
            'side' => ($side === 'buy') ? 'BUY' : 'SELL',
            'quantity' => $this->amount_to_precision($symbol, $amount),
        );
        if ($price !== null) {
            $request['price'] = $this->price_to_precision($symbol, $price);
        }
        $triggerPrice = $this->safe_string_2($params, 'triggerPrice', 'stopPrice');
        if ($triggerPrice !== null) {
            $request['type'] = 'STOP_' . strtoupper($type);
            $request['stop_Price'] = $this->price_to_precision($symbol, $triggerPrice); // sic, capital P
        }
        $clientOrderId = $this->safe_string($params, 'clientOrderId');
        if ($clientOrderId !== null) {
            $request['client_id'] = $clientOrderId;
        }
        $params = $this->omit($params, array( 'triggerPrice', 'stopPrice', 'clientOrderId' ));
        $response = $this->privatePostV1AccountOrders($this->extend($request, $params));
        //
        //     {
        //         "message": "...",
        //         "result": {
        //             "symbol": "BTCUSDT", "type": "LIMIT", "side": "BUY", "clientOrderId": "test_clientId",
        //             "price": "82494", "origQty": "0.001", "executedQty": "0", "executedSum": "0", "executedPrice": "0",
        //             "sum": "82.494", "executedPercent": 0, "status": "NEW", "active": true, "fee": "0", "fills": [],
        //             "stopPrice": null, "transactTime": 1700000000, "created_at": "2023-11-14T22:13:20Z"
        //         },
        //         "success": true
        //     }
        //
        $result = $this->safe_dict($response, 'result', array());
        return $this->parse_order($result, $market);
    }

    public function parse_order(array $order, ?array $market = null): array {
        $marketId = $this->safe_string($order, 'symbol');
        $market = $this->safe_market($marketId, $market);
        $statuses = $this->safe_dict($this->options, 'orderStatuses', array());
        $status = $this->safe_string($order, 'status');
        $type = $this->safe_string_lower($order, 'type'); // LIMIT, MARKET, STOP_LIMIT, STOP_MARKET
        if ($type !== null) {
            $type = str_replace('stop_', '', $type);
        }
        $average = $this->safe_string($order, 'executedPrice');
        if (Precise::string_eq($average, '0')) {
            $average = null;
        }
        // wallex identifies orders by clientOrderId for fetch and cancel
        $clientOrderId = $this->safe_string($order, 'clientOrderId');
        return $this->safe_order(array(
            'id' => $clientOrderId,
            'clientOrderId' => $clientOrderId,
            'timestamp' => $this->parse8601($this->safe_string($order, 'created_at')),
            'datetime' => null,
            'lastTradeTimestamp' => null,
            'symbol' => $market['symbol'],
            'type' => $type,
            'timeInForce' => null,
            'postOnly' => null,
            'side' => $this->safe_string_lower($order, 'side'),
            'price' => $this->safe_string($order, 'price'),
            'triggerPrice' => $this->safe_string($order, 'stopPrice'),
            'amount' => $this->safe_string($order, 'origQty'),
            'filled' => $this->safe_string($order, 'executedQty'),
            'remaining' => null,
            'cost' => $this->safe_string($order, 'executedSum'),
            'average' => $average,
            'status' => $this->safe_string($statuses, $status, $status),
            'fee' => array(
                'cost' => $this->safe_string($order, 'fee'),
                'currency' => null,
            ),
            'trades' => null,
            'info' => $order,
        ), $market);
    }

    public function sign(mixed $path, mixed $api = 'public', $method = 'GET', $params = array(), ?array $headers = null, ?string $body = null) {
        $url = $this->urls['api']['rest'] . '/' . $this->implode_params($path, $params);
        $query = $this->omit($params, $this->extract_params($path));
        $headers = array();
        if ($api === 'private') {
            // wallex authenticates with the raw key in x-api-key, there is no secret and no hmac signature
            $this->check_required_credentials();
            $headers['X-API-KEY'] = $this->apiKey;
        }
        if ($method === 'GET') {
            if (count($query) > 0) {
                $url .= '?' . $this->urlencode($query);
            }
        } else {
            $body = $this->json($query);
            $headers['Content-Type'] = 'application/json';
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }

    public function handle_errors(int $httpCode, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        if ($response === null) {
            return null;
        }
        //
        //     { "code": 1201, "message": "invalid API key format", "result": {}, "success": false }
        //
        $success = $this->safe_bool($response, 'success');
        if ($success === false) {
            $code = $this->safe_string($response, 'code');
            if ($code === '1201') {
                throw new AuthenticationError($this->id . ' ' . $body);
            }
            throw new ExchangeError($this->id . ' ' . $body);
        }
        return null;
    }
